actions.script:
def targetApp = ec.web.parameters.targetApp ?: ""

// Base structure definition
def topology = [
    nodes: [],
    edges: []
]

if (!targetApp) {
    ec.web.sendJsonResponse(topology)
    return
}

// Natively localize directory path boundaries based on user target selection
File componentDir = new File("runtime/component/${targetApp}")
if (!componentDir.exists()) {
    ec.web.sendJsonResponse(topology)
    return
}

int startX = 100
int startY = 150

// 1. Scan and parse XML Screen definitions
File screenDir = new File(componentDir, "screen")
if (screenDir.exists()) {
    screenDir.eachFileRecurse { file ->
        if (file.name.endsWith(".xml")) {
            topology.nodes.add([
                id: "scr_${file.name.replace('.', '_')}",
                type: "screen",
                label: file.name,
                x: startX,
                y: startY,
                expanded: false
            ])
            startY += 120
        }
    }
}

// Reset placement vectors for secondary service column column
startX = 450
startY = 150

// 2. Scan and parse Entity definitions
File entityDir = new File(componentDir, "entity")
if (entityDir.exists()) {
    entityDir.eachFileRecurse { file ->
        if (file.name.endsWith(".xml")) {
            topology.nodes.add([
                id: "ent_${file.name.replace('.', '_')}",
                type: "entity",
                label: file.name,
                x: startX,
                y: startY,
                expanded: false
            ])
            startY += 120
        }
    }
}

// Fallback scaffolding: If the newly created component directory is pristine, populate base targets
if (topology.nodes.isEmpty()) {
    topology.nodes = [
        [id: "scr_default", type: "screen", label: "MainDashboard.xml", x: 100, y: 150, expanded: false],
        [id: "srv_default", type: "service", label: "StandardValidationRoutine.groovy", x: 450, y: 150, expanded: false],
        [id: "ent_default", type: "entity", label: "DataExtensionModel.xml", x: 800, y: 150, expanded: false]
    ]
}

ec.web.sendJsonResponse(topology)
